findings.suggestion:
按 EXPECTED_TYPES 做校验与显式转换，失败即报错：
def coerce(config):
    result = {}
    for key, typ in EXPECTED_TYPES.items():
        if key not in config:
            continue
        value = config[key]
        if typ is bool and isinstance(value, str):
            value = value.strip().lower() in ("1", "true", "yes", "on")
        if not isinstance(value, typ):
            raise ValueError(f"配置项 {key} 期望 {typ.__name__}，实际 {type(value).__name__}")
        result[key] = value
    return result

